function phaFreePort():int{$socket=stream_socket_server('tcp://127.0.0.1:0',$errno,$error);if($socket===false)throw new TestFailure('loopback port');$name=(string)stream_socket_get_name($socket,false);fclose($socket);return (int)substr($name,strrpos($name,':')+1);}
function phaParse(string $raw):array{[$head,$responseBody]=array_pad(explode("\r\n\r\n",$raw,2),2,'');$lines=explode("\r\n",$head);$statusLine=array_shift($lines);preg_match('/^HTTP\/\d\.\d (\d{3})/',$statusLine,$match);$parsed=[];foreach($lines as $line){if(!str_contains($line,':'))continue;[$name,$value]=explode(':',$line,2);$parsed[strtolower(trim($name))][]=trim($value);}return ['status'=>(int)($match[1]??0),'headers'=>$parsed,'body'=>$responseBody,'raw'=>$raw];}
function phaRawHostValues(string $raw):array{[$head]=explode("\r\n\r\n",$raw,2);$values=[];foreach(array_slice(explode("\r\n",$head),1) as $line){if(!str_contains($line,':'))continue;[$name,$value]=explode(':',$line,2);if(strcasecmp($name,'Host')!==0)continue;if(str_starts_with($value,' '))$value=substr($value,1);$values[]=$value;}return $values;}
function phaRawWire(int $port,string $method,string $target,array $headers=[],string $body='',int $timeout=5,string $host='adversarial.example'):array{$socket=stream_socket_client("tcp://127.0.0.1:{$port}",$errno,$error,$timeout);if($socket===false)throw new TestFailure('HTTP connect');try{$request="{$method} {$target} HTTP/1.1\r\nHost: {$host}\r\nConnection: close\r\n";foreach($headers as $name=>$value)$request.="{$name}: {$value}\r\n";$request.="\r\n{$body}";fwrite($socket,$request);fflush($socket);stream_set_timeout($socket,$timeout);$raw='';while(!feof($socket)){$chunk=fread($socket,65536);if($chunk===false)break;$raw.=$chunk;}return phaParse($raw);}finally{fclose($socket);}}
