function phaBodyNotRead(int $port,string $method,string $target,string $secret,string $sentinel):array{assertSameValue(false,file_exists($sentinel),'php://input sentinel absent before 405');$body="opaque-body:{$secret}:".str_repeat("\xA5",257);$response=phaRaw($port,$method,$target,['Content-Type'=>'application/octet-stream','Content-Length'=>(string)strlen($body)],$body);assertSameValue(false,str_contains($response['raw'],$secret),'opaque body secret not reflected');assertSameValue(false,file_exists($sentinel),'405 must not open php://input');return $response;}
